export default function Button({ onClick, label = "Click Me", disabled = false }) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 active:scale-[0.98] transition disabled:opacity-50"
    >
      {label}
    </button>
  );
}
```

